#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<double> sensorReadings = {23.5, 24.1, 22.8, 25.0, 23.9};
    int index;
    std::cout << "Enter sensor index to check: ";
    std::cin >> index;

    if (index < 0 || index >= sensorReadings.size()) {
        std::cout << "Invalid index!\n";
        return 1;
    }

    double reading;
    if (reading = 999) {
        std::cout << "Warning: Sensor fault detected!\n";
    }

    std::cout << "Sensor reading at index " << index << ": " << sensorReadings[index] << "\n";
    return 0;
}

